package com.djibtout.backend.controller;
import com.djibtout.backend.security.CurrentUser;import com.djibtout.backend.entity.*;import com.djibtout.backend.repository.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@RestController @RequestMapping("/api/seller/documents") public class SellerDocumentController{private final UserRepository users;private final SellerStoreRepository stores;private final SellerDocumentRepository documents;public SellerDocumentController(UserRepository u,SellerStoreRepository s,SellerDocumentRepository d){users=u;stores=s;documents=d;}private User user(Authentication a){return CurrentUser.of(users,a);}private SellerStore store(Authentication a){User u=user(a);return u==null?null:stores.findBySeller(u).orElse(null);}@GetMapping public ResponseEntity<?> list(Authentication a){SellerStore s=store(a);if(s==null)return ResponseEntity.status(403).build();return ResponseEntity.ok(documents.findByStoreOrderByCreatedAtDesc(s).stream().map(d->Map.of("id",d.getId(),"type",d.getDocumentType(),"fileName",d.getFileName(),"contentType",d.getContentType(),"createdAt",d.getCreatedAt())).toList());}@PostMapping public ResponseEntity<?> upload(Authentication a,@RequestParam MultipartFile file,@RequestParam String type)throws Exception{SellerStore s=store(a);if(s==null)return ResponseEntity.status(403).build();if(file.isEmpty()||file.getSize()>10*1024*1024)return ResponseEntity.badRequest().body(Map.of("message","Document vide ou supérieur à 10 Mo."));String mime=file.getContentType();if(!List.of("application/pdf","image/jpeg","image/png").contains(mime))return ResponseEntity.badRequest().body(Map.of("message","Seuls PDF, JPG et PNG sont acceptés."));byte[] bytes=file.getBytes();if("application/pdf".equals(mime)&&(bytes.length<5||bytes[0]!='%'||bytes[1]!='P'||bytes[2]!='D'||bytes[3]!='F'))return ResponseEntity.badRequest().body(Map.of("message","Fichier PDF invalide."));SellerDocument d=new SellerDocument();d.setStore(s);d.setDocumentType(type);d.setFileName(Optional.ofNullable(file.getOriginalFilename()).orElse("document"));d.setContentType(mime);d.setContent(bytes);documents.save(d);return ResponseEntity.ok(Map.of("id",d.getId(),"fileName",d.getFileName(),"type",type));}@GetMapping("/{id}") public ResponseEntity<?> download(Authentication a,@PathVariable Long id){User u=user(a);SellerDocument d=documents.findById(id).orElse(null);if(u==null||d==null||!(u.getRole()==Role.ADMIN||d.getStore().getSeller().getId().equals(u.getId())))return ResponseEntity.status(403).build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.getContentType())).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+d.getFileName().replace("\"","")+"\"").body(d.getContent());}@DeleteMapping("/{id}") public ResponseEntity<?> delete(Authentication a,@PathVariable Long id){SellerStore s=store(a);SellerDocument d=documents.findById(id).orElse(null);if(s==null||d==null||!d.getStore().getId().equals(s.getId()))return ResponseEntity.status(403).build();documents.delete(d);return ResponseEntity.noContent().build();}}
